const CARRO_POR_CATEGORIA: Record<VeiculoCategoria, ComponentType<{ className?: string }>> = {
  sedan:      CarroSedanSvg,
  hatch:      CarroHatchSvg,
  suv:        CarroSuvSvg,
  picape:     CarroPicapeSvg,
  van:        CarroVanSvg,
  utilitario: CarroUtilitarioSvg,
  esportivo:  CarroEsportivoSvg,
};

/** Ilustração do veículo conforme a categoria cadastrada (única fonte para tabela e modal). */
export function CarroCategoriaSvg({ categoria, className }: { categoria: VeiculoCategoria; className?: string }) {
  const Carro = CARRO_POR_CATEGORIA[categoria] ?? CarroHatchSvg;
  return <Carro className={className} />;
}
